function refreshIngredientLatest(ids=[]){const wanted=new Set(A(ids).filter(Boolean));for(const i of A(ops.pricing?.ingredients)){if(wanted.size&&!wanted.has(i.id))continue;const hs=A(ops.pricing?.ingredientPriceHistory).filter(h=>h.ingredientId===i.id&&N(h.priceToman)>0).sort((a,b)=>{const dc=dateCmp(D(b.date),D(a.date));return dc||String(b.createdAt||'').localeCompare(String(a.createdAt||''))});if(hs.length){i.lastPurchasePriceToman=N(hs[0].priceToman);i.latestPriceToman=N(hs[0].priceToman);i.lastPurchaseDate=D(hs[0].date)}}}
