function opsView(){if(!ops.inv||!ops.pricing){setTimeout(load,0);return pageHead('انبار و کنترل مصرف','')+'<div class="card"><div class="empty">در حال بارگذاری اطلاعات انبار و قیمت‌گذاری…</div></div>'}const meta=coreMeta(ops.tab);return pageHead(meta[0],meta[1])+nav()+corePane(ops.tab)}
